do $$ declare bad int; actual int; begin
  with corpus as (select q.id,q.display_ref from questions q join source_papers sp on sp.id=q.source_paper_id join syllabi sy on sy.id=sp.syllabus_id join components c on c.id=q.component_id where sy.code='9618' and sp.source_url is not null and sp.year=2025 and q.marks>0 and c.number=4), r as (select s.*,f.id fid,t.id tid from _9618_dep_p4_2025 s left join corpus f on f.display_ref=s.from_ref left join corpus t on t.display_ref=s.to_ref) select count(*) into bad from r where fid is null or tid is null;
  if bad<>0 then raise exception '9618 Paper 4 2025 dependency snapshot unresolved refs=%',bad; end if;
  delete from question_dependencies d using questions q,source_papers sp,syllabi sy,components c where d.question_id=q.id and q.source_paper_id=sp.id and sp.syllabus_id=sy.id and q.component_id=c.id and sy.code='9618' and sp.source_url is not null and sp.year=2025 and q.marks>0 and c.number=4;
  insert into question_dependencies(question_id,depends_on_id,kind,strength,evidence,detected_by,confidence) select f.id,t.id,s.kind,'required','Audited source-backed Cambridge 9618 dependency snapshot.','dependency-reconcile-2026-09-02',0.99 from _9618_dep_p4_2025 s join questions f on f.display_ref=s.from_ref join questions t on t.display_ref=s.to_ref;
  select count(*) into actual from question_dependencies d join questions q on q.id=d.question_id join source_papers sp on sp.id=q.source_paper_id join syllabi sy on sy.id=sp.syllabus_id join components c on c.id=q.component_id where sy.code='9618' and sp.source_url is not null and sp.year=2025 and q.marks>0 and c.number=4;
  if actual<>34 then raise exception '9618 Paper 4 2025 expected 34 dependency edges, got %',actual; end if;
end $$;
